head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//기관 코드
scwin.vScrenID = "ULDINS90100.xml";
scwin.param1 = "";
scwin.flag = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 기관 코드 조회한다.
 ***********************************************/
scwin.ins_search = function(instNm, mktID) {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS90100_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.listDeptCdInquiry" + "&{P}INST_NM=" + instNm + "&{P}FLAG=" + scwin.flag + "&{P}MKTID=" + scwin.param1;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (row == 0) return;
    if (dts_List.getCellData(row, "STD_CD_INST_STAT_CD") != '1') {
        $c.win.alert('기관상태가 정상인 기관만 선택 가능 합니다.\n선택을 원할 경우 기관관리화면에서 상태를 변경 후 선택이 가능합니다.');
        return;
    }
    var BND_INST_CD = dts_List.getCellData(row, "BND_INST_CD");
    var INST_NM = dts_List.getCellData(row, "INST_NM");
    $c.frame.path("../").ins_popupRtn_cdnm(BND_INST_CD, INST_NM);
    await $c.frame.CloseFrame();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_search_onclick = function() {
    scwin.flag = "1";
    scwin.ins_search(txb_INST_NM.getValue());
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.txb_INST_NM_onkeyup = function() {
    scwin.flag = "1";
    fn_DelChar(this);
    if (txb_INST_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search(txb_INST_NM.getValue());
        } else {

        }
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_2);
    scwin.flag = "0";
    txb_INST_NM.focus();
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(arrPar);
        scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] != undefined) ? arrPar[0] : "");
        //alert(param1);
        if (scwin.param1 == "") return;
        scwin.ins_search("", scwin.param1);
    }
};
